async function takeModerationAction(r:any,action:'restrict'|'ban'|'delete'){const targetId=r.targetUserId||r.reported_user_id||r.reportedPost?.author_id;if(!targetId){ER('This report has no identifiable account to moderate.');return;}const duration=action==='restrict'?window.prompt('Temporary restriction duration in days: enter 1, 7, or 30','7'):null;if(action==='restrict'&&duration===null)return;const hours=action==='restrict'?Number(duration)*24:null;if(action==='restrict'&&![24,168,720].includes(hours as number)){ER('Choose 1, 7, or 30 days.');return;}const reason=window.prompt(action==='delete'?'Reason for marking this account deleted (soft deletion):':action==='ban'?'Reason for permanently banning this account:':'Reason for temporarily restricting this account:',r.reason||'Violation of Vibe.ly Community Guidelines');if(reason===null)return;if(reason.trim().length<5){ER('Please provide a reason of at least 5 characters.');return;}if(!window.confirm((action==='delete'?'Mark this account as deleted? The account will be disabled and hidden, and the user will see a notice on next sign-in.':action==='ban'?'Permanently ban this account?':'Temporarily restrict this account for '+duration+' day(s)?')))return;B(true);ER('');ME('');const {error}=await supabase.rpc('admin_take_moderation_action',{p_target_user_id:targetId,p_action:action,p_reason:reason.trim(),p_duration_hours:hours,p_report_id:r.id});if(error){ER(error.message);B(false);return;}ME(action==='delete'?'Account marked deleted and notice queued for the user.':action==='ban'?'Account banned and notice sent to the user.':'Temporary restriction applied and notice sent to the user.');await loadReports();if(profile.permissions?.includes('*')||profile.permissions?.includes('users.view')||profile.permissions?.includes('users.manage'))await loadUsers(true);B(false);}
